// This file is not generated by Speakeasy — it is 'vf auth signup' and
// 'vf auth login --signup'.
//
// Signup is the browser login flow with prompt=create on the authorization
// request, so the authorization server opens its signup screen instead of the
// login screen. The account is created in the browser — reCAPTCHA, SSO, terms,
// and email verification all stay there — and the CLI never sees a password.
// The session is stored exactly as 'vf auth login' stores it.

package oauth

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

// Workspace is a workspace the new account belongs to.
type Workspace struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

// WorkspaceLister lists the signed-in account's workspaces. It is supplied by
// the generated command package, because building an API client from here
// would import internal/client, which already imports this package.
type WorkspaceLister func(ctx context.Context, cmd *cobra.Command) ([]Workspace, error)

// workspaceLister is set by AddSignupCommand. Nil skips the workspace check.
var workspaceLister WorkspaceLister

// The first workspace of a new account is created asynchronously, so it may
// not be listed yet when the redirect lands. Package variables so tests can
// shorten them.
var (
	workspaceWait = 30 * time.Second
	workspacePoll = 2 * time.Second
)

// AddSignupCommand registers 'vf auth signup' on the auth command. lister is
// used after signup to show the new account's workspaces, for both
// 'vf auth signup' and 'vf auth login --signup'.
func AddSignupCommand(authCmd *cobra.Command, lister WorkspaceLister) {
	workspaceLister = lister

	cmd := &cobra.Command{
		Use:   "signup",
		Short: "Create a Voiceflow account in the browser and sign in",
		Long: `Create a Voiceflow account and sign in to it.

This opens your browser on the Voiceflow signup screen. You create the account
there — the CLI never asks for or handles a password — and once you finish, the
session is stored exactly as 'vf auth login' stores it. 'vf auth login --signup'
does the same.

Use --email to prefill the signup form. Signup includes verifying your email
address, so the CLI waits up to 15 minutes by default (--login-timeout).

In agent mode no browser is opened. The signup URL is printed as a JSON event
with status "awaiting_signup", for the agent to hand to the user, who creates
the account in their own browser. The command keeps waiting until they finish,
so run it in the background and read its output.`,
		Example: "  vf auth signup\n  vf auth signup --email you@example.com",
		Args:    cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runBrowserLogin(cmd, true)
		},
	}

	flags := cmd.Flags()
	flags.String(flagEmail, "", "Email address to prefill on the signup form")
	flags.Bool(flagNoBrowser, false, "Print the signup URL instead of opening a browser (always on in agent mode)")
	flags.StringArray(flagScope, nil, "OAuth scope to request (repeatable). Defaults to the scopes the authorization server advertises.")
	flags.Duration(flagLoginTimeout, DefaultSignupTimeout, "How long to wait for the browser to complete signup")
	for _, name := range []string{flagEmail, flagNoBrowser, flagScope, flagLoginTimeout} {
		_ = flags.SetAnnotation(name, "speakeasy:group", []string{"Authentication"})
	}

	authCmd.AddCommand(cmd)
}

// checkSignupFlags rejects flags that pick a non-browser login, since an
// account can only be created in the browser.
func checkSignupFlags(cmd *cobra.Command) error {
	if manual, err := cmd.Flags().GetBool(flagManual); err == nil && manual {
		return fmt.Errorf("signup creates the account in the browser, so it cannot be combined with --%s", flagManual)
	}
	if noInteractive, err := cmd.Flags().GetBool("no-interactive"); err == nil && noInteractive {
		return fmt.Errorf("signup creates the account in the browser, so it cannot be combined with --no-interactive")
	}
	if flag := cmd.Flags().Lookup("token"); flag != nil && flag.Changed {
		return fmt.Errorf("signup creates the account in the browser, so it cannot be combined with --token")
	}
	return nil
}

// isSignupURL reports whether an authorization URL asks for the signup screen.
// Login drops prompt=create when the server does not support it, so the URL is
// the reliable record of what was actually requested.
func isSignupURL(authURL string) bool {
	u, err := url.Parse(authURL)
	return err == nil && u.Query().Get("prompt") == PromptCreate
}

// accountFromToken names the signed-in account from the access token's claims,
// without verifying it: the token was just issued to this client over TLS, and
// the result is only displayed. It returns "" for a token that is not a JWT.
func accountFromToken(token string) string {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return ""
	}
	payload, err := base64.RawURLEncoding.DecodeString(strings.TrimRight(parts[1], "="))
	if err != nil {
		return ""
	}
	var claims struct {
		Email   string `json:"email"`
		Subject string `json:"sub"`
	}
	if err := json.Unmarshal(payload, &claims); err != nil {
		return ""
	}
	if claims.Email != "" {
		return claims.Email
	}
	if claims.Subject != "" {
		// Voiceflow access tokens carry only the numeric user ID.
		return "user " + claims.Subject
	}
	return ""
}

// waitForWorkspaces lists the account's workspaces, retrying for a short time
// while the list is empty or the request fails, since the first workspace of
// a new account is created asynchronously. It returns the last error only when
// no attempt succeeded.
func waitForWorkspaces(ctx context.Context, cmd *cobra.Command) ([]Workspace, error) {
	if workspaceLister == nil {
		return nil, nil
	}
	ctx, cancel := context.WithTimeout(ctx, workspaceWait)
	defer cancel()

	var lastErr error
	for {
		workspaces, err := workspaceLister(ctx, cmd)
		if err == nil {
			lastErr = nil
			if len(workspaces) > 0 {
				return workspaces, nil
			}
		} else {
			lastErr = err
		}

		select {
		case <-ctx.Done():
			return nil, lastErr
		case <-time.After(workspacePoll):
		}
	}
}

// signupNextSteps are the commands suggested once the account exists.
var signupNextSteps = []string{
	"vf workspace list    List your workspaces",
	"vf auth whoami       Show the stored session",
	"vf docs --help       Search the Voiceflow documentation from the terminal",
	"vf explore           Browse and run every command interactively",
}

// writeSignupResult prints the account, its workspaces, and next steps after
// a signup in human mode.
func writeSignupResult(w io.Writer, workspaces []Workspace, err error) {
	switch {
	case len(workspaces) > 0:
		fmt.Fprintln(w, "\nWorkspaces:")
		for _, ws := range workspaces {
			fmt.Fprintf(w, "  %s (%s)\n", ws.Name, ws.ID)
		}
	case err != nil:
		fmt.Fprintf(w, "\nCould not list workspaces yet (%v); run 'vf workspace list' in a minute.\n", err)
	case workspaceLister != nil:
		fmt.Fprintln(w, "\nYour first workspace is still being set up; run 'vf workspace list' in a minute.")
	}

	fmt.Fprintln(w, "\nNext steps:")
	for _, step := range signupNextSteps {
		fmt.Fprintf(w, "  %s\n", step)
	}
}
